@prefix dash: <http://datashapes.org/dash#> .
@prefix rdf4j: <http://rdf4j.org/schema/rdf4j#> .

rdf4j:SHACLShapeGraph {

    ex:Person
        a rdfs:Class, sh:NodeShape ;
        sh:or (
            [
                sh:closed true;
                	    sh:ignoredProperties ( ex:thisPropertyIsIgnored ex:thisPropertyIsAlsoIgnored ) ;
                        sh:property
                            [
                                sh:path ex:name ;
                            ],
                            [
                                sh:path ex:age ;
                            ],
                	        [
                                sh:path rdf:type;
                            ]
                        ;
            ]

            [

            sh:closed true;
            	    sh:ignoredProperties ( ex:thisPropertyIsIgnored_or ex:thisPropertyIsAlsoIgnored ) ;
                    sh:property
                        [
                            sh:path ex:name_or ;
                        ],
                        [
                            sh:path ex:age_or ;
                        ],
            	        [
                            sh:path rdf:type;
                        ]
                    ;

            ]


        );

    .

}

