  ex:PersonShape a sh:NodeShape;
    sh:targetClass foaf:Person;
    sh:property [
        sh:path foaf:age;
        sh:or ([
              sh:datatype xsd:integer
            ] [
              sh:datatype xsd:int
            ]);
        sh:minCount 1;
        sh:maxCount 1;
        sh:minInclusive 1
      ], [
        sh:path foaf:name;
        sh:maxCount 5;
        sh:nodeKind sh:Literal;
        sh:minLength 1
      ], [
        sh:path foaf:interest;
        sh:nodeKind sh:BlankNodeOrIRI
      ], [
        sh:path foaf:knows;
        sh:nodeKind sh:BlankNodeOrIRI
      ], [
        sh:path foaf:mbox;
        sh:nodeKind sh:IRI;
        sh:flags "i";
        sh:pattern "(mailto)(:).*?(@).*?"
      ] .
}

@prefix mms:   <https://mms.researchstudio.at/mms#> .
@prefix sh:    <http://www.w3.org/ns/shacl#> .
@prefix dtype: <http://www.linkedmodel.org/schema/dtype#> .
@prefix rdf4j: <http://rdf4j.org/schema/rdf4j#> .


rdf4j:SHACLShapeGraph {
    mms:EnumerationTypeShape
        a              sh:NodeShape ;
        sh:targetClass mms:EnumerationType ;
        sh:property    [ sh:path     dtype:hasMember ;
                         sh:minCount 1 ;
                         sh:node     mms:EnumerationMemberShape ] .

    mms:EnumerationMemberShape
        a           sh:NodeShape ;
        sh:property [ sh:path     [ sh:inversePath dtype:hasMember ] ;
                      sh:minCount 1 ;
                      sh:maxCount 1 ;
                      sh:class    mms:EnumerationType ] .
}

