rdf4j:SHACLShapeGraph {
  ex:shape1
  	a sh:NodeShape ;
  	rsx:targetShape [
  	        sh:property [
          		sh:path ex:info ;
          		sh:hasValue "blue" ; # we have to have at least have "blue" as a value for ex:info
          		sh:and ( [ sh:hasValue "blue" ; ] ) ; # all values for ex:info have to be "blue"
          	]
  	];

  	sh:property [
  	   sh:path ex:info2 ;
  	   sh:minCount 1;
  	]

  	 .

}

